// Writes test/web/fixture.g.dart: the engine's test app's (test/fixture_app/) files and the bundle the
// CLI compiled, as Dart constants, for test/web/ (browser tests cannot read
// files or, in `flutter test`, assets). Run after `dart run tool/metacode.dart test/fixture_app`.

import 'dart:convert';
import 'dart:io';

const projectDir = 'test/fixture_app';

void main() {
  String quote(String path) =>
      jsonEncode(File('$projectDir/.generated/$path').readAsStringSync())
          .replaceAll(r'$', r'\$');
  File('test/web/fixture.g.dart').writeAsStringSync('''
// GENERATED by `dart run tool/web_fixture.dart`. Do not edit.
// ignore_for_file: lines_longer_than_80_chars

/// `.generated/files.json`: the project's text files.
const filesJson = ${quote('files.json')};

/// `.generated/bundle.json`, as the CLI compiled it.
const bundleJson = ${quote('bundle.json')};
''');
  stdout.writeln('Wrote test/web/fixture.g.dart');
}
